const recoverDCPV2AdmissionLease = `-- name: RecoverDCPV2AdmissionLease :execrows
UPDATE dcp_v2_admission SET
    lease_owner = ?, lease_epoch = ?, lease_token = ?,
    recovery_generation = recovery_generation + 1, updated_at = ?
WHERE admission_id = ? AND status = 'leased' AND lease_owner = ? AND lease_epoch = ?
  AND lease_token = ? AND dispatch_fence = '' AND recovery_generation = ?
`

type RecoverDCPV2AdmissionLeaseParams struct {
	LeaseOwner         string
	LeaseEpoch         string
	LeaseToken         string
	UpdatedAt          time.Time
	AdmissionID        string
	LeaseOwner_2       string
	LeaseEpoch_2       string
	LeaseToken_2       string
	RecoveryGeneration int64
}

func (q *Queries) RecoverDCPV2AdmissionLease(ctx context.Context, arg RecoverDCPV2AdmissionLeaseParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, recoverDCPV2AdmissionLease,
		arg.LeaseOwner,
		arg.LeaseEpoch,
		arg.LeaseToken,
		arg.UpdatedAt,
		arg.AdmissionID,
		arg.LeaseOwner_2,
		arg.LeaseEpoch_2,
		arg.LeaseToken_2,
		arg.RecoveryGeneration,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

